manifest=json.loads((out/'audio-manifest.json').read_text())
for row in manifest['calls']:row['sha256']=hashlib.sha256((out/'audio'/(row['id']+'.wav')).read_bytes()).hexdigest()
manifest.update(total_unique_synthesized_files=len(manifest['calls']),automatic_retries=False,maximum_synthesis_starts_per_minute=12,maximum_parallel_synthesis_workers=2);(out/'audio-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n');shutil.copy2(out/'audio-manifest.json',root/'validation/submission-demo-v2-tts.json')
# Preserve explicit assets only, never a browser profile, cookie file or CLI config.
