with zipfile.ZipFile(out/'LingoLive-Media-Assets.zip','w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
 for f in assets:z.write(f,'LingoLive-Media/'+str(f.relative_to(out)))
