 p=root/name;d=json.loads(p.read_text());d.update(demo_video_version='2.1 (web 1.9, audio repaired)',archived_demo_video_version='1.5',public_materials_url=base+'index.html');d['demo_v2'].update(production_status='verified_publication_pending',new_audio_generated=True,new_video_generated=True,actual_seconds=v['seconds'],planned_learning_introduced_seconds=138,learning_introduced_seconds=v['learning_introduced_near_end_seconds'],voice_model='gemini-3.1-flash-tts-preview',actual_asr_error_and_correction_shown=True);d['material_status']['demo']=f"V2.1 audio repaired: {v['seconds']:.3f} seconds, all {v['expected_voice_events']} voice events verified, artificial ambience removed; actual app and speech correction retained";d['material_status']['public_downloads']='New v2 files prepared; publication verification pending';d['material_status']['writeup_pdf']='Updated web 1.9 detailed seven-page A4 PDF, including actual v2 audio, simulation and ASR limitations';p.write_text(json.dumps(d,indent=2)+'\n')
