(out/'index.html').write_text(html)
with zipfile.ZipFile(out/'LingoLive-Submission.zip','w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
 for name in ['LingoLive-Demo.mp4','LingoLive-Demo.srt','LingoLive-Demo.vtt','LingoLive-Writeup.pdf','LingoLive-Proposal.pdf','DEMO-TRANSCRIPT-V2.md','video-verification.json','audio-verification.json','README.txt']:z.write(out/name,'LingoLive-Submission/'+name)
 assert z.testzip() is None
# Text and binary payload scan, including every uncompressed ZIP member.
patterns={'oauth_access':rb'ya29\.[A-Za-z0-9_.-]{20,}','google_key':rb'(?:AIza[A-Za-z0-9_-]{25,}|AQ\.[A-Za-z0-9_-]{25,})','github_token':rb'(?:gh[pousr]_|github_pat_)[A-Za-z0-9_]{20,}','private_key':rb'-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----'}
findings=[]
for name in ['LingoLive-Submission.zip','LingoLive-Media-Assets.zip']:
 with zipfile.ZipFile(out/name) as z:
  for member in z.namelist():
   raw=z.read(member)
   for rule,pattern in patterns.items():
    if re.search(pattern,raw):findings.append(dict(file=member,rule=rule))
assert not findings,findings
(out/'artifact-audit.json').write_text(json.dumps(dict(unresolved_findings=findings,zip_members_scanned=True,limits='Pattern scan plus explicit file allowlist; no cookie/profile/CLI files included'),indent=2)+'\n')
print(json.dumps({'video_bytes':(out/'LingoLive-Demo.mp4').stat().st_size,'submission_zip_bytes':(out/'LingoLive-Submission.zip').stat().st_size,'media_assets_zip_bytes':(out/'LingoLive-Media-Assets.zip').stat().st_size,'artifact_secret_findings':findings}))
